package main

func Unique(nums []int) []int {
    seen := make(map[int]struct{}, len(nums))
    out := make([]int, 0, len(nums))
    for _, n := range nums {
        if _, ok := seen[n]; ok {
            continue
        }
        seen[n] = struct{}{}
        out = append(out, n)
    }
    return out
}

