import "sync"

func ParallelSum(parts [][]int) int {
    var (
        wg    sync.WaitGroup
        mu    sync.Mutex
        total int
    )
    for _, p := range parts {
        wg.Add(1)
        go func(nums []int) {
            defer wg.Done()
            s := 0
            for _, n := range nums {
                s += n
            }
            mu.Lock()
            total += s
            mu.Unlock()
        }(p)
    }
    wg.Wait()
    return total
}

